'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Navbar } from '@/components/layout/Navbar';
import { Button } from '@/components/ui/Button';
import { vendors } from '@/lib/templates';
import { UtensilsCrossed, Wine, Flower2, ArrowRight, X, Star, MapPin, Phone, Mail, Check } from 'lucide-react';
import type { Vendor } from '@/lib/types';

const categoryIcons = {
  catering: UtensilsCrossed,
  bartending: Wine,
  decorators: Flower2,
};

const categoryLabels = {
  catering: 'Catering',
  bartending: 'Bartending',
  decorators: 'Decorators',
};

export default function VendorsPage() {
  const [selectedVendor, setSelectedVendor] = useState<Vendor | null>(null);

  const groupedVendors = vendors.reduce((acc, vendor) => {
    if (!acc[vendor.category]) acc[vendor.category] = [];
    acc[vendor.category].push(vendor);
    return acc;
  }, {} as Record<string, typeof vendors>);

  return (
    <div className="min-h-screen bg-[#F7F7F5]">
      <Navbar />
      
      {/* Header */}
      <section className="pt-32 pb-12 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto text-center">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <h1 className="text-4xl lg:text-5xl font-bold text-[#111111] mb-4">
              Event Vendors
            </h1>
            <p className="text-lg text-[#5A5A5F] max-w-2xl mx-auto">
              Connect with top-rated professionals to bring your design to life
            </p>
          </motion.div>
        </div>
      </section>

      {/* Vendors by Category */}
      <section className="pb-24 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto space-y-16">
          {Object.entries(groupedVendors).map(([category, categoryVendors], catIndex) => {
            const Icon = categoryIcons[category as keyof typeof categoryIcons];
            return (
              <motion.section
                key={category}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: catIndex * 0.1 }}
              >
                {/* Category Header */}
                <div className="flex items-center gap-4 mb-8">
                  <div className="w-14 h-14 bg-[#C6A85C]/10 rounded-2xl flex items-center justify-center">
                    <Icon className="w-7 h-7 text-[#C6A85C]" />
                  </div>
                  <div>
                    <h2 className="text-2xl font-bold text-[#111111]">
                      {categoryLabels[category as keyof typeof categoryLabels]}
                    </h2>
                    <p className="text-[#8C8C92]">{categoryVendors.length} professionals</p>
                  </div>
                </div>

                {/* Vendors Grid */}
                <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
                  {categoryVendors.map((vendor, i) => (
                    <motion.div
                      key={vendor.id}
                      initial={{ opacity: 0, y: 20 }}
                      whileInView={{ opacity: 1, y: 0 }}
                      viewport={{ once: true }}
                      transition={{ delay: 0.1 + i * 0.05 }}
                      className="group bg-white rounded-2xl p-6 shadow-md border border-[#E5E5E8] hover:shadow-lg transition-all duration-300"
                    >
                      {/* Header */}
                      <div className="flex items-start justify-between mb-5">
                        <div className="w-16 h-16 bg-gradient-to-br from-[#111111] to-[#333333] rounded-2xl flex items-center justify-center text-white text-2xl font-bold">
                          {vendor.name.charAt(0)}
                        </div>
                        <div className="flex items-center gap-1 px-3 py-1.5 bg-[#C6A85C]/10 rounded-full">
                          <Star className="w-4 h-4 text-[#C6A85C] fill-[#C6A85C]" />
                          <span className="text-sm font-semibold text-[#111111]">{vendor.rating}</span>
                        </div>
                      </div>
                      
                      {/* Info */}
                      <h3 className="text-xl font-semibold text-[#111111] mb-2">{vendor.name}</h3>
                      <p className="text-[#5A5A5F] text-sm mb-5 line-clamp-2">{vendor.description}</p>
                      
                      {/* Services */}
                      <div className="flex flex-wrap gap-2 mb-6">
                        {vendor.services.slice(0, 3).map((service, j) => (
                          <span key={j} className="px-3 py-1 bg-[#F7F7F5] rounded-full text-xs font-medium text-[#5A5A5F]">
                            {service}
                          </span>
                        ))}
                      </div>

                      <Button 
                        variant="outline" 
                        className="w-full group/btn"
                        onClick={() => setSelectedVendor(vendor)}
                      >
                        View Profile
                        <ArrowRight className="w-4 h-4 ml-2 transition-transform group-hover/btn:translate-x-1" />
                      </Button>
                    </motion.div>
                  ))}
                </div>
              </motion.section>
            );
          })}
        </div>
      </section>

      {/* Vendor Detail Modal */}
      <AnimatePresence>
        {selectedVendor && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm"
            onClick={() => setSelectedVendor(null)}
          >
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white rounded-3xl max-w-2xl w-full max-h-[90vh] overflow-hidden shadow-2xl"
            >
              {/* Header */}
              <div className="relative h-40 bg-gradient-to-r from-[#111111] to-[#333333]">
                <button
                  onClick={() => setSelectedVendor(null)}
                  className="absolute top-4 right-4 w-10 h-10 bg-white/10 backdrop-blur-sm rounded-full flex items-center justify-center hover:bg-white/20 transition-colors"
                >
                  <X className="w-5 h-5 text-white" />
                </button>
                
                {/* Avatar */}
                <div className="absolute -bottom-10 left-8">
                  <div className="w-20 h-20 bg-white rounded-2xl flex items-center justify-center text-3xl font-bold text-[#111111] border-4 border-white shadow-lg">
                    {selectedVendor.name.charAt(0)}
                  </div>
                </div>
              </div>

              {/* Content */}
              <div className="pt-14 pb-8 px-8">
                {/* Title Row */}
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h2 className="text-2xl font-bold text-[#111111]">{selectedVendor.name}</h2>
                    <p className="text-[#8C8C92] capitalize">{selectedVendor.category} Services</p>
                  </div>
                  <div className="flex items-center gap-1 px-4 py-2 bg-[#C6A85C]/10 rounded-full">
                    <Star className="w-5 h-5 text-[#C6A85C] fill-[#C6A85C]" />
                    <span className="text-lg font-bold text-[#111111]">{selectedVendor.rating}</span>
                  </div>
                </div>

                <p className="text-[#5A5A5F] mb-8">{selectedVendor.description}</p>

                {/* Services */}
                <div className="mb-8">
                  <h3 className="text-sm font-semibold text-[#8C8C92] uppercase tracking-wider mb-4">Services</h3>
                  <div className="flex flex-wrap gap-2">
                    {selectedVendor.services.map((service, j) => (
                      <span key={j} className="px-4 py-2 bg-[#F7F7F5] rounded-xl text-sm font-medium text-[#111111] flex items-center gap-2">
                        <Check className="w-4 h-4 text-[#C6A85C]" />
                        {service}
                      </span>
                    ))}
                  </div>
                </div>

                {/* Contact Info */}
                <div className="grid sm:grid-cols-2 gap-4 mb-8">
                  <div className="flex items-center gap-3 p-4 bg-[#F7F7F5] rounded-xl">
                    <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center text-[#8C8C92] shadow-sm">
                      <Phone className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="text-xs text-[#8C8C92]">Phone</p>
                      <p className="text-[#111111] font-medium text-sm">{selectedVendor.phone}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3 p-4 bg-[#F7F7F5] rounded-xl">
                    <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center text-[#8C8C92] shadow-sm">
                      <Mail className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="text-xs text-[#8C8C92]">Email</p>
                      <p className="text-[#111111] font-medium text-sm">{selectedVendor.email}</p>
                    </div>
                  </div>
                </div>

                {/* Location */}
                <div className="flex items-center gap-2 text-[#8C8C92] mb-8">
                  <MapPin className="w-4 h-4" />
                  <span>{selectedVendor.location}</span>
                </div>

                {/* Actions */}
                <div className="flex gap-4">
                  <Button className="flex-1" size="lg">
                    Contact Vendor
                    <ArrowRight className="w-4 h-4 ml-2" />
                  </Button>
                  <Button variant="outline" onClick={() => setSelectedVendor(null)} size="lg">
                    Close
                  </Button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
